function visit(n){if(n.nodeType===3){let el=n.parentElement;if(!el||el.closest('script,style,textarea,option,#interfaceLanguage,.prompt,#work button:not(#submit):not(#askHint):not(#undo):not(#audio):not(#speak):not(:last-child),.hw,.hcard p,.phrase-recall summary,#work .tile'))return;if(el.parentElement?.id==='work'&&el.tagName==='BUTTON'&&!el.id&&!el.textContent.includes('ورّيني')&&!original.has(n))return;let old=original.get(n);if(old&&n.data!==old.last)old=null;let src=old?.src??n.data;if(!/[\u0600-\u06ff]/.test(src))return;
let target=lang==='de'?trans(src):src;if(target!==n.data)n.data=target;original.set(n,{src,last:target});return}
if(n.nodeType!==1||n.matches('script,style,textarea,option'))return;for(let c of n.childNodes)visit(c)}
function apply(){document.documentElement.lang=lang==='ary'?'ar-MA':'de';document.documentElement.dir=lang==='ary'?'rtl':'ltr';select.value=lang;select.parentNode.firstChild.data=lang==='de'?'Sprache':'لغة الواجهة';visit(document.body)}
